const d = $json.body || $json || {};
const title = String(d.title || 'Untitled task').slice(0, 200);
const description = String(d.description || '');
// TODO: set your Linear team UUID (same as the cerebro workflow's Build task).
const LINEAR_TEAM_ID = 'REPLACE_WITH_LINEAR_TEAM_UUID';
const body = {
  query: 'mutation CreateIssue($teamId: String!, $title: String!, $description: String) { issueCreate(input: { teamId: $teamId, title: $title, description: $description }) { success issue { identifier title url } } }',
  variables: { teamId: LINEAR_TEAM_ID, title, description }
};
return [{ json: { requestBody: JSON.stringify(body) } }];

const r = $json;
const res = r && r.data && r.data.issueCreate;
const issue = res && res.issue;
if (res && res.success && issue) {
  return [{ json: { ok: true, identifier: issue.identifier, title: issue.title, url: issue.url } }];
}
return [{ json: { ok: false, error: 'Linear did not create the issue', detail: JSON.stringify((r && r.errors) || r).slice(0, 300) } }];

const d = $json.body || $json || {};
const title = String(d.title || 'Evento').slice(0, 200);
const start = String(d.start || '');
let end = String(d.end || '');
if (!end && start) { try { end = new Date(new Date(start).getTime() + 3600000).toISOString(); } catch (e) {} }
return [{ json: { title, start, end, description: String(d.description || '') } }];

const r = $json;
if (r && r.id) {
  return [{ json: { ok: true, id: r.id, summary: r.summary || '', htmlLink: r.htmlLink || '', start: r.start } }];
}
return [{ json: { ok: false, error: 'Calendar did not create the event', detail: JSON.stringify(r).slice(0, 300) } }];

// Upcoming events (next 7 days): drop finished ones, sort, format date + time.
const tz = 'America/Puerto_Rico';
const now = Date.now();
function startRaw(e) { return (e.start && (e.start.dateTime || e.start.date)) || null; }
function endMs(e) { const r = (e.end && (e.end.dateTime || e.end.date)) || startRaw(e); const t = Date.parse(r); return isNaN(t) ? now : t; }
function fmtDate(e) {
  const r = startRaw(e); if (!r) return '';
  try { return new Date(r).toLocaleDateString('es-PR', { timeZone: tz, weekday: 'short', day: 'numeric', month: 'short' }); } catch (x) { return ''; }
}
function fmtTime(e) {
  if (e.start && e.start.dateTime) { try { return new Date(e.start.dateTime).toLocaleTimeString('es-PR', { timeZone: tz, hour: '2-digit', minute: '2-digit' }); } catch (x) {} }
  return 'Todo el día';
}
const all = $input.all().map(i => i.json).filter(e => e && (e.id || e.summary));
const upcoming = all.filter(e => endMs(e) >= now);
upcoming.sort((a, b) => String(startRaw(a)).localeCompare(String(startRaw(b))));
const out = upcoming.map(e => ({ date: fmtDate(e), time: fmtTime(e), title: e.summary || '(sin título)', start: startRaw(e) }));
return [{ json: { ok: true, count: out.length, events: out } }];
